// Generated: one realistic-ish HTML payload, compressed several ways, so a decoder benchmark
// compares like with like. BR5 is what a CDN compresses on the fly; BR11 is what it serves from
// cache for static assets — the pair tests whether harder compression makes DECODING cheaper.
const B64=(s)=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
export const RAW_BYTES = 262563;
export const BR = B64("");
export const BR11 = B64("");
export const GZ = B64("");
